module ToyTrain(\n    input clk,\n    input rst_n,\n    input start,\n    input [6:0] n,\n    input [7:0] m,\n    input [6:0] a_i [0:199],\n    input [6:0] b_i [0:199],\n    output reg [31:0] ans_i [0:99],\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] PROCESS   = 3'd1;\n    localparam [2:0] COMPUTE_I = 3'd2;\n    localparam [2:0] COMPUTE_J = 3'd3;\n    localparam [2:0] DONE_ST   = 3'd4;\n    \n    reg [2:0] state;\n\n    // Internal registers\n    reg [7:0] m_reg;\n    reg [6:0] n_reg;\n    reg [7:0] k;  \n    reg [6:0] i;\n    reg [6:0] j;\n    reg [31:0] current_max;\n    \n    // Arrays\n    reg [7:0] count [0:99];\n    reg [6:0] min_dist [0:99];\n\n    // Temporary wires for comb logic\n    wire [6:0] current_j;\n    wire [6:0] current_b;\n    wire signed [7:0] temp_diff;\n    wire signed [7:0] adjusted_diff;\n    wire [6:0] current_diff;\n    \n    wire signed [7:0] dist_signed;\n    wire signed [7:0] dist_adjusted;\n    wire [6:0] dist_i_j;\n    wire [14:0] term;\n    wire [31:0] current_value;\n\n    assign current_j      = a_i[k] - 7'd1;\n    assign current_b      = b_i[k] - 7'd1;\n    assign temp_diff      = $signed({1'b0, current_b}) - $signed({1'b0, current_j});\n    assign adjusted_diff  = (temp_diff < 0) ? (temp_diff + $signed({1'b0, n_reg})) : temp_diff;\n    assign current_diff   = adjusted_diff[6:0];\n    \n    assign dist_signed    = $signed({1'b0, j}) - $signed({1'b0, i});\n    assign dist_adjusted  = (dist_signed < 0) ? (dist_signed + $signed({1'b0, n_reg})) : dist_signed;\n    assign dist_i_j       = dist_adjusted[6:0];\n    assign term           = (count[j] - 8'd1) * $signed({1'b0, n_reg});\n    assign current_value  = $unsigned(dist_i_j) + $unsigned(min_dist[j]) + $unsigned(term);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done           <= 1'b0;\n            state          <= IDLE;\n            m_reg          <= 8'd0;\n            n_reg          <= 7'd0;\n            k              <= 8'd0;\n            i              <= 7'd0;\n            j              <= 7'd0;\n            current_max    <= 32'd0;\n            begin : reset_arrays\n                integer idx;\n                for (idx = 0; idx < 100; idx = idx + 1) begin\n                    count[idx]     <= 8'd0;\n                    min_dist[idx]  <= 7'd127;\n                    ans_i[idx]     <= 32'd0;\n                end\n            end\n        end else begin\n            // Default done deassert\n            if (state != DONE_ST) done <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state          <= PROCESS;\n                        m_reg          <= m;\n                        n_reg          <= n;\n                        k              <= 8'd0;\n                        i              <= 7'd0;\n                        j              <= 7'd0;\n                        current_max    <= 32'd0;\n                        \n                        begin : init_arrays\n                            integer idx;\n                            for (idx = 0; idx < 100; idx = idx + 1) begin\n                                count[idx]     <= 8'd0;\n                                min_dist[idx]  <= 7'd127;\n                            end\n                        end\n                    end\n                end\n\n                PROCESS: begin\n                    if (k < m_reg) begin\n                        count[current_j] <= count[current_j] + 8'd1;\n                        if (current_diff < min_dist[current_j]) begin\n                            min_dist[current_j] <= current_diff;\n                        end\n                        k <= k + 8'd1;\n                    end else begin\n                        state <= COMPUTE_I;\n                    end\n                end\n\n                COMPUTE_I: begin\n                    j <= 7'd0;\n                    current_max <= 32'd0;\n                    state <= COMPUTE_J;\n                end\n\n                COMPUTE_J: begin\n                    if (j < n_reg) begin\n                        if (count[j] > 8'd0) begin\n                            if (current_value > current_max) begin\n                                current_max <= current_value;\n                            end\n                        end\n                        j <= j + 7'd1;\n                    end else begin\n                        ans_i[i] <= current_max;\n                        if (i < (n_reg - 7'd1)) begin\n                            i <= i + 7'd1;\n                            state <= COMPUTE_I;\n                        end else begin\n                            state <= DONE_ST;\n                        end\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule